"""Migrated invoiced-order workflow, validation, and total recomputation rules."""

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


_CENTS = Decimal("0.01")


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _decimal_nvl(value: Any, default: Any = 0) -> Decimal:
    """Return a Decimal value, treating missing and blank values as the default."""
    if value is None or value == "":
        value = default
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply the permitted status transition rules for an invoiced order."""
    if order["STAT_CD"] != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated_order = dict(order)

    if new_status == "X":
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    if new_status == "I":
        return updated_order, [], []

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live line extensions and the order total for a mutable order."""
    updated_order = dict(order)
    updated_lines = [dict(line) for line in lines]

    if order["STAT_CD"] in ("I", "X"):
        return updated_order, updated_lines, []

    total = Decimal("0")

    for line in updated_lines:
        if line.get("DEL_FLG") == "Y":
            continue

        quantity = _decimal_nvl(line.get("QTY"))
        unit_price = _decimal_nvl(line.get("UNIT_PRC"))
        extension = _round_cents(quantity * unit_price)
        line["EXT_AMT"] = float(extension)
        total += extension

    discount_percent = _decimal_nvl(order.get("DISC_PCT"))
    recomputed_total = _round_cents(
        total * (Decimal("100") - discount_percent) / Decimal("100")
    )
    stored_total = _decimal_nvl(order.get("TOT_AMT"))

    updated_order["TOT_AMT"] = float(recomputed_total)
    audits = ["ORD_RETOTAL"] if stored_total != recomputed_total else []

    return updated_order, updated_lines, audits
